<section class="page-header"><div><span class="status">ADM · WhatsApp</span><h1>Mídias recebidas</h1><p class="meta">Acompanhe arquivos sincronizados e tente novamente quando houver uma falha temporária.</p></div><form method="post" action="<?= $escape($basePath) ?>/whatsapp/media/sync"><?= $csrfField ?><button type="submit"><i class="fa-solid fa-arrows-rotate"></i> Sincronizar pendentes</button></form></section>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<div class="media-summary"><article><small>Conexão com a Meta</small><strong><?= $credentialsReady?'Disponível':'Aguardando credenciais' ?></strong></article><article><small>Arquivos órfãos para limpeza</small><strong><?= (int)$orphanCandidates ?></strong></article></div>
<div class="table-responsive"><table><thead><tr><th>Contato</th><th>Linha / unidade</th><th>Arquivo</th><th>Situação</th><th>Tentativas</th><th>Próxima tentativa</th><th>Diagnóstico</th><th></th></tr></thead><tbody><?php if($items===[]):?><tr><td colspan="8">Nenhuma mídia registrada.</td></tr><?php else:foreach($items as$item):?><?php $state=(string)($item['media_sync_status']??'pending');?><tr><td><strong><?= $escape($item['contact_name']?:$item['wa_contact_id']) ?></strong><small><?= $escape(date('d/m/Y H:i',strtotime((string)$item['message_at']))) ?></small></td><td><?= $escape($item['line_name']) ?><small><?= $escape($item['unit_name']) ?></small></td><td><?= $escape($item['file_name']?:$item['message_type']) ?><small><?= $escape($item['mime_type']?:'Tipo ainda não identificado') ?></small></td><td><span class="media-state <?= $escape($state) ?>"><?= $state==='synced'?'Sincronizada':($state==='processing'?'Processando':($state==='failed'?'Falhou':'Pendente')) ?></span></td><td><?= (int)$item['media_attempts'] ?>/6</td><td><?= $item['media_next_attempt_at']?$escape(date('d/m/Y H:i',strtotime((string)$item['media_next_attempt_at']))):'—' ?></td><td><?= $escape($item['media_error']?:'—') ?></td><td><?php if($state!=='synced'):?><form method="post" action="<?= $escape($basePath) ?>/whatsapp/media/<?= (int)$item['id'] ?>/retry"><?= $csrfField ?><button class="btn btn-sm" type="submit">Tentar novamente</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div>
<style>.media-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin:1rem 0}.media-summary article{display:grid;gap:.3rem;padding:1rem;border:1px solid #dfe5e9;border-radius:.8rem;background:#fff}.media-summary small,td small{display:block;color:var(--inter-muted)}.media-state{display:inline-flex;padding:.2rem .55rem;border-radius:999px;font-size:.78rem;font-weight:700}.media-state.synced{color:#176b3a;background:#eaf8ef}.media-state.pending,.media-state.processing{color:#8a5a00;background:#fff4cc}.media-state.failed{color:#a3131b;background:#fff0f1}@media(max-width:760px){.media-summary{grid-template-columns:1fr}}</style>
